const fs = require('fs');
const path = require('path');

function readJsonLines(filePath) {
    if (!fs.existsSync(filePath)) return [];
    return fs.readFileSync(filePath, 'utf8')
        .split(/\r?\n/)
        .filter(Boolean)
        .map(line => JSON.parse(line));
}

/**
 * Load causal SAFE-Alert outputs generated by backtest_safe_alert.py.
 * Each timeline row carries forward the most recent 1H and 4H output so the
 * strategy parser can evaluate both horizons at any candle timestamp.
 */
function loadHistoricalPredictions({ symbol, startDate, endDate }) {
    const predictionDir = process.env.MODEL_PREDICTIONS_DIR
        || path.resolve(__dirname, '../../data/model_predictions');
    const normalizedSymbol = String(symbol || '').toUpperCase();
    const startMs = new Date(startDate).getTime();
    const endMs = new Date(endDate).getTime();
    const events = [];

    for (const horizon of ['1h', '4h']) {
        const filePath = path.join(predictionDir, `historical_predictions_${horizon}.jsonl`);
        for (const row of readJsonLines(filePath)) {
            if (String(row.symbol || '').toUpperCase() !== normalizedSymbol) continue;
            const timeMs = new Date(row.time).getTime();
            if (!Number.isFinite(timeMs) || timeMs > endMs) continue;
            events.push({ ...row, horizon, timeMs });
        }
    }

    events.sort((a, b) => a.timeMs - b.timeMs || a.horizon.localeCompare(b.horizon));
    const latest = {};
    const timeline = [];

    for (const event of events) {
        latest[event.horizon] = event;
        // Keep warm-up events before startDate for causal carry-forward.
        if (event.timeMs < startMs) continue;
        timeline.push({
            time: event.time,
            direction_1h: latest['1h']?.direction,
            confidence_1h: latest['1h']?.confidence,
            probabilities_1h: latest['1h']?.probabilities,
            direction_4h: latest['4h']?.direction,
            confidence_4h: latest['4h']?.confidence,
            probabilities_4h: latest['4h']?.probabilities,
            model_used: 'SAFEAlertNet',
        });
    }

    return timeline;
}

module.exports = { loadHistoricalPredictions };
